package com.zhineng.platform.evaluation.selfevaluation.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.zhineng.platform.common.audit.OperationLogRepository;import com.zhineng.platform.common.user.service.CurrentUserService;import com.zhineng.platform.evaluation.selfevaluation.dto.SelfEvaluationDtos.*;import com.zhineng.platform.evaluation.selfevaluation.repository.SelfEvaluationRepository;import com.zhineng.platform.evaluation.selfevaluation.storage.SelfEvaluationStorage;
import java.io.*;import java.nio.file.*;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;
@Service @Transactional public class SelfEvaluationService{
 private static final long MAX=10L*1024*1024;private static final Set<String>EXT=Set.of("pdf","doc","docx","xls","xlsx","jpg","jpeg","png","zip"),WARN=Set.of("OPEN","CONFIRMED","IGNORED","RESOLVED");
 private final SelfEvaluationRepository repo;private final CurrentUserService users;private final OperationLogRepository logs;private final SelfEvaluationStorage storage;private final ObjectMapper json;
 public SelfEvaluationService(SelfEvaluationRepository r,CurrentUserService u,OperationLogRepository l,SelfEvaluationStorage s,ObjectMapper j){repo=r;users=u;logs=l;storage=s;json=j;}
 @Transactional(readOnly=true)public List<Map<String,Object>>versions(){return repo.versions();}@Transactional(readOnly=true)public List<Map<String,Object>>orgs(){return repo.orgs();}
 @Transactional(readOnly=true)public List<Map<String,Object>>tasks(){return repo.tasks();}
 @Transactional(readOnly=true)public Map<String,Object>task(long id){Map<String,Object>t=repo.task(id);if(t==null)nf("TASK_NOT_FOUND","自评任务不存在");t.put("organizations",repo.taskOrgs(id));return t;}
 public Map<String,Object>createTask(TaskRequest q){if(q==null||q.indicatorVersionId()==null||repo.version(q.indicatorVersionId())==null)bad("INVALID_VERSION","请选择已发布指标版本");if(q.orgUnitIds()==null||q.orgUnitIds().isEmpty())bad("ORGS_REQUIRED","至少选择一个参评机构");int year=q.evaluationYear()==null?0:q.evaluationYear();if(year<1900||year>2999)bad("INVALID_YEAR","年度无效");String type=up(q.taskType());if(!Set.of("ANNUAL","SPECIAL").contains(type))bad("INVALID_TYPE","任务类型无效");LocalDate start=date(q.startDate(),"开始日期"),end=date(q.endDate(),"结束日期");if(end.isBefore(start))bad("INVALID_RANGE","结束日期不能早于开始日期");long uid=uid(),id;try{id=repo.addTask(req(q.taskCode(),"任务编码"),req(q.taskName(),"任务名称"),year,type,start.toString(),end.toString(),trim(q.description()),q.indicatorVersionId(),uid);Set<Long>seen=new HashSet<>();for(Long org:q.orgUnitIds()){if(org==null||repo.org(org)==null)bad("INVALID_ORG","参评机构无效");if(!seen.add(org))bad("DUPLICATE_ORG","参评机构重复");repo.addTaskOrg(id,org);}}catch(SelfEvaluationException e){throw e;}catch(Exception e){conflict("TASK_DUPLICATE","任务编码或参评机构重复");return null;}repo.taskHistory(id,null,"DRAFT","创建自评任务",uid);Map<String,Object>a=task(id);log("M2-12","SELF_TASK",id,"CREATE",a);return a;}
 public Map<String,Object>publish(long id){Map<String,Object>t=task(id);if(!"DRAFT".equals(t.get("status")))conflict("TASK_NOT_DRAFT","仅草稿可发布");List<Map<String,Object>>ind=repo.sourceIndicators(num(t.get("indicator_version_id")));if(ind.isEmpty())conflict("NO_INDICATORS","指标版本没有启用三级指标");List<Map<String,Object>>orgs=repo.taskOrgs(id);List<Long>snapshots=new ArrayList<>();for(Map<String,Object>i:ind)snapshots.add(repo.addSnapshot(id,i,t.get("end_date").toString()));for(Map<String,Object>o:orgs)for(Long s:snapshots)repo.addEntry(num(o.get("id")),s,uid());if(repo.publish(id,uid())!=1)conflict("PUBLISH_FAILED","任务状态已变化");repo.taskHistory(id,"DRAFT","PUBLISHED","发布并冻结指标快照",uid());Map<String,Object>a=task(id);log("M2-12","SELF_TASK",id,"PUBLISH",a);return a;}
 public Map<String,Object>cancel(long id,ReviewRequest q){Map<String,Object>t=task(id);String from=t.get("status").toString();if(repo.cancelTask(id,uid())!=1)conflict("TASK_NOT_CANCELLABLE","已完成或已取消任务不能取消");String opinion=req(q==null?null:q.opinion(),"取消原因");repo.taskHistory(id,from,"CANCELLED",opinion,uid());Map<String,Object>a=task(id);log("M2-12","SELF_TASK",id,"CANCEL",a);return a;}
 @Transactional(readOnly=true)public Map<String,Object>form(long orgId){Map<String,Object>o=repo.taskOrg(orgId);if(o==null)nf("FORM_NOT_FOUND","机构自评表不存在");o.put("entries",repo.entries(orgId));return o;}
 public Map<String,Object>saveEntry(long id,EntryRequest q){Map<String,Object>e=repo.entry(id);if(e==null)nf("ENTRY_NOT_FOUND","自评指标不存在");if(!Set.of("NOT_STARTED","DRAFT","RETURNED").contains(e.get("org_status")))conflict("FORM_READ_ONLY","已提交自评只读，退回后才能修改");Double score=q.selfScore();double max=((Number)e.get("standard_score")).doubleValue();if(score==null||score<0||score>max)bad("INVALID_SCORE","自评分必须在0至标准分之间");String desc=req(q.performanceDescription(),"履职说明");if(desc.length()<5)bad("DESCRIPTION_TOO_SHORT","履职说明至少5个字");if(repo.saveEntry(id,score,desc,trim(q.completionStatus()),rv(q.rowVersion()),uid())!=1)conflict("STALE_ENTRY","指标已被修改");long org=num(e.get("task_org_id"));repo.recalc(org);repo.syncTaskStatus(num(e.get("task_id")));Map<String,Object>a=form(org);log("M2-12","SELF_ENTRY",id,"SAVE",a);return a;}
 public Map<String,Object>submit(long orgId,ReviewRequest q){Map<String,Object>o=form(orgId);String status=o.get("status").toString();if(!Set.of("DRAFT","RETURNED").contains(status))conflict("FORM_NOT_EDITABLE","仅草稿或退回表可提交");for(Map<String,Object>e:cast(o.get("entries"))){if(e.get("self_score")==null||trim(e.get("performance_description"))==null)bad("FORM_INCOMPLETE","所有指标必须填写自评分和履职说明");}if(repo.orgStatus(orgId,status,"SUBMITTED",trim(q==null?null:q.opinion()),uid())!=1)conflict("STATUS_CHANGED","自评状态已变化");repo.orgHistory(orgId,status,"SUBMITTED","提交自评",uid());repo.syncTaskStatus(num(o.get("task_id")));Map<String,Object>a=form(orgId);log("M2-12","SELF_FORM",orgId,"SUBMIT",a);return a;}
 public Map<String,Object>review(long orgId,ReviewRequest q){Map<String,Object>o=form(orgId);if(!"SUBMITTED".equals(o.get("status")))conflict("NOT_SUBMITTED","仅已提交自评可复核");String action=up(q==null?null:q.action()),to="CONFIRM".equals(action)?"COMPLETED":"RETURN".equals(action)?"RETURNED":null;if(to==null)bad("INVALID_ACTION","复核动作无效");String opinion=req(q.opinion(),"复核意见");if(repo.orgStatus(orgId,"SUBMITTED",to,opinion,uid())!=1)conflict("STATUS_CHANGED","自评状态已变化");repo.orgHistory(orgId,"SUBMITTED",to,opinion,uid());repo.syncTaskStatus(num(o.get("task_id")));Map<String,Object>a=form(orgId);log("M2-12","SELF_FORM",orgId,action,a);return a;}
 public Map<String,Object>requirement(long snapshotId,RequirementRequest q){int count=q.requiredMaterialCount()==null?0:q.requiredMaterialCount();if(count<0)bad("INVALID_COUNT","必传数量不能为负数");String ext=req(q.allowedExtensions(),"允许格式").toLowerCase(Locale.ROOT);for(String x:ext.split(","))if(!EXT.contains(x.trim()))bad("INVALID_EXTENSION","包含不支持的材料格式");if(repo.requirement(snapshotId,count,ext,trim(q.namingKeywords()),trim(q.dueDate()))!=1)nf("SNAPSHOT_NOT_FOUND","指标快照不存在");return Map.of("id",snapshotId,"updated",true);}
 public Map<String,Object>upload(long entryId,MaterialRequest q,MultipartFile file){Map<String,Object>e=repo.entry(entryId);if(e==null)nf("ENTRY_NOT_FOUND","自评指标不存在");if(!Set.of("NOT_STARTED","DRAFT","RETURNED").contains(e.get("org_status")))conflict("FORM_READ_ONLY","已提交自评不能调整材料");if(file==null||file.isEmpty()||file.getSize()>MAX)bad("INVALID_FILE","材料为空或超过10MB");String ext=ext(file.getOriginalFilename());if(!EXT.contains(ext))bad("UNSUPPORTED_FILE","材料格式不支持");String group=trim(q==null?null:q.versionGroup());if(group==null)group=UUID.randomUUID().toString();Map<String,Object>old=repo.latestMaterial(group);int ver=old==null?1:((Number)old.get("version_no")).intValue()+1;String category=trim(q==null?null:q.category()),source="MANUAL",classStatus="CONFIRMED";if(category==null){category=suggest(file.getOriginalFilename(),e.get("indicator_code").toString());source="RULE";classStatus=Boolean.TRUE.equals(q==null?null:q.confirmClassification())?"CONFIRMED":"SUGGESTED";}String documentDate=trim(q==null?null:q.documentDate());if(documentDate!=null)date(documentDate,"材料日期");SelfEvaluationStorage.Stored stored=null;try{stored=storage.store(file.getInputStream(),ext);long aid=repo.addAttachment(entryId,safe(file.getOriginalFilename()),stored.storedName(),stored.relativePath(),file.getContentType(),ext,file.getSize(),uid());if(old!=null)repo.retireMaterial(num(old.get("id")));long mid=repo.addMaterial(entryId,aid,group,ver,req(q==null?null:q.materialName(),"材料名称"),category,trim(q.description()),source,classStatus,documentDate,uid());Map<String,Object>a=repo.materials(entryId).stream().filter(x->num(x.get("id"))==mid).findFirst().orElseThrow();log("M2-13","SELF_MATERIAL",mid,old==null?"UPLOAD":"REPLACE",a);return a;}catch(Exception ex){if(stored!=null)storage.cleanup(stored.relativePath());if(ex instanceof SelfEvaluationException se)throw se;bad("UPLOAD_FAILED","材料上传失败："+ex.getMessage());return null;}}
 public List<Map<String,Object>>materials(long entry){repo.entry(entry);return repo.materials(entry);}
 public Map<String,Object>confirmMaterial(long id,String category){if(repo.confirmMaterial(id,req(category,"材料分类"))!=1)nf("MATERIAL_NOT_FOUND","材料不存在");return Map.of("id",id,"confirmed",true);}
 public Map<String,Object>disableMaterial(long id){if(repo.materialStatus(id,"INACTIVE")!=1)nf("MATERIAL_NOT_FOUND","材料不存在");log("M2-13","SELF_MATERIAL",id,"DISABLE",Map.of("id",id));return Map.of("id",id,"status","INACTIVE");}
 @Transactional(readOnly=true)public Download download(long id)throws IOException{Map<String,Object>a=repo.attachment(id);if(a==null)nf("ATTACHMENT_NOT_FOUND","材料附件不存在");return new Download(storage.resolve(a.get("storage_path").toString()),a.get("original_name").toString(),Objects.toString(a.get("content_type"),"application/octet-stream"));}
 public Map<String,Object>runWarnings(long taskId,Long orgId){task(taskId);long run=repo.addRun(taskId,orgId,uid());int checks=0,warnings=0;for(Map<String,Object>c:repo.warningCandidates(taskId,orgId)){checks++;List<Map<String,Object>>materials=repo.materials(num(c.get("entry_id"))).stream().filter(x->"ACTIVE".equals(x.get("status"))&&num(x.get("is_current"))==1).toList();int required=((Number)c.get("required_material_count")).intValue();if(materials.size()<required){repo.addWarning(run,num(c.get("task_org_id")),num(c.get("id")),materials.isEmpty()?"MISSING":"INSUFFICIENT","必传材料需要"+required+"份，当前"+materials.size()+"份");warnings++;}for(Map<String,Object>m:materials){String extension=m.get("extension").toString().toLowerCase(Locale.ROOT);Set<String>allowed=new HashSet<>(Arrays.asList(c.get("allowed_extensions").toString().toLowerCase(Locale.ROOT).split(",")));if(!allowed.contains(extension)){repo.addWarning(run,num(c.get("task_org_id")),num(c.get("id")),"FORMAT","材料格式不符合要求："+extension);warnings++;}String kw=trim(c.get("naming_keywords"));if(kw!=null&&!matches(m.get("original_name").toString(),kw)){repo.addWarning(run,num(c.get("task_org_id")),num(c.get("id")),"NAMING","文件名缺少规定关键词："+kw);warnings++;}String documentDate=trim(m.get("document_date"));if(documentDate!=null&&LocalDate.parse(documentDate).isBefore(LocalDate.parse(c.get("start_date").toString()))){repo.addWarning(run,num(c.get("task_org_id")),num(c.get("id")),"EXPIRED","材料日期早于本次自评周期");warnings++;}}String due=trim(c.get("due_date"));if(due!=null&&LocalDate.now().isAfter(LocalDate.parse(due))&&materials.size()<required){repo.addWarning(run,num(c.get("task_org_id")),num(c.get("id")),"OVERDUE","已超过材料截止日期");warnings++;}}repo.finishRun(run,checks,warnings);Map<String,Object>result=Map.of("runId",run,"totalChecks",checks,"warningCount",warnings,"warnings",repo.warnings(run));log("M2-14","SELF_WARNING_RUN",run,"RULE_CHECK",result);return result;}
 @Transactional(readOnly=true)public List<Map<String,Object>>warnings(Long run){return repo.warnings(run);}
 public Map<String,Object>processWarning(long id,WarningProcessRequest q){if(repo.warning(id)==null)nf("WARNING_NOT_FOUND","预警不存在");String s=up(q==null?null:q.status());if(!WARN.contains(s))bad("INVALID_STATUS","预警状态无效");repo.processWarning(id,s,trim(q.opinion()),uid());return repo.warning(id);}
 public Map<String,Object>remind(long id){Map<String,Object>w=repo.warning(id);if(w==null)nf("WARNING_NOT_FOUND","预警不存在");repo.remind(id,"模拟机构经办人","请补充或修正自评材料："+w.get("message"),uid());log("M2-14","SELF_WARNING",id,"LOCAL_REMIND",w);return Map.of("warningId",id,"channel","LOCAL_SIMULATION","sent",true);}
 @Transactional(readOnly=true)public List<Map<String,Object>>reminders(){return repo.reminders();}
 private boolean matches(String name,String kw){for(String k:kw.split("[,， ]+"))if(!k.isBlank()&&name.contains(k))return true;return false;}private String suggest(String filename,String code){if(filename!=null&&filename.toUpperCase(Locale.ROOT).contains(code.toUpperCase(Locale.ROOT)))return"INDICATOR_EVIDENCE";return"OTHER";}private List<Map<String,Object>>cast(Object v){return(List<Map<String,Object>>)v;}private LocalDate date(String v,String label){try{return LocalDate.parse(req(v,label));}catch(Exception e){bad("INVALID_DATE",label+"格式必须为YYYY-MM-DD");return null;}}private int rv(Integer v){if(v==null)bad("ROW_VERSION_REQUIRED","缺少版本号");return v;}private long uid(){return users.getCurrentUser().id();}private long num(Object v){return((Number)v).longValue();}private String req(Object v,String l){String s=trim(v);if(s==null)bad("REQUIRED_FIELD",l+"不能为空");return s;}private String trim(Object v){if(v==null)return null;String s=v.toString().trim();return s.isEmpty()?null:s;}private String up(String v){return v==null?null:v.trim().toUpperCase(Locale.ROOT);}private String ext(String n){if(n==null||!n.contains("."))return"";return n.substring(n.lastIndexOf('.')+1).toLowerCase(Locale.ROOT);}private String safe(String n){return n==null?"file":Path.of(n).getFileName().toString().replaceAll("[\\r\\n]","_");}private String toJson(Object v){try{return json.writeValueAsString(v);}catch(Exception e){return"{}";}}
 private void log(String m,String t,long id,String a,Object after){logs.success(m,t,id,a,uid(),"LOCAL","/api/self-evaluations",null,toJson(after));}private void bad(String c,String m){throw new SelfEvaluationException(HttpStatus.BAD_REQUEST,c,m);}private void conflict(String c,String m){throw new SelfEvaluationException(HttpStatus.CONFLICT,c,m);}private void nf(String c,String m){throw new SelfEvaluationException(HttpStatus.NOT_FOUND,c,m);}public record Download(Path path,String name,String type){}
}
